using UnityEngine;
using UnityEngine.SceneManagement;

/// <summary>
/// 鐜╁绠＄悊鍣?(鎸佷箙鍖栧崟渚? 鈥?璐熻矗鍔ㄦ€佺敓鎴?Player 骞惰法鍦烘櫙淇濈暀銆?
///
/// 閫氳繃 [RuntimeInitializeOnLoadMethod] 鍦ㄩ涓満鏅姞杞藉墠鑷姩鍒涘缓锛?
/// 閫氳繃 SceneManager.sceneLoaded 浜嬩欢鍦ㄦ瘡娆″満鏅姞杞芥椂妫€娴嬶細
/// - 鍦烘櫙涓湁 Player锛圱ag="Player"锛夆啋 鏍囪 DontDestroyOnLoad 淇濈暀
/// - 鍦烘櫙涓棤 Player 鈫?浠?Player 棰勫埗浣撳姩鎬佺敓鎴?
///
/// 渚濊禆: 椤圭洰涓瓨鍦?Tag="Player" 鐨?Player 棰勫埗浣?(Assets/Prefab/Player.prefab)
/// 琚?MapManager / EnemyCore 閫氳繃 GameObject.FindGameObjectWithTag("Player") 鑷姩鍙戠幇
/// </summary>
public class PlayerManager : MonoBehaviour
{
    public static PlayerManager Instance { get; private set; }

    [Header("Player 棰勫埗浣?)]
    [SerializeField] private GameObject _playerPrefab;

    [Header("鍑虹敓浣嶇疆")]
    [SerializeField] private Vector3 _spawnPosition = Vector3.zero;

    /// <summary>鍦烘櫙鍔犺浇鍚庤Е鍙? 鍙傛暟涓?(Player GameObject)</summary>
    public event System.Action<GameObject> OnPlayerReady;

    /// <summary>褰撳墠 Player GameObject 寮曠敤</summary>
    public GameObject CurrentPlayer { get; private set; }

    // ==================== 鐢熷懡鍛ㄦ湡 ====================

    /// <summary>
    /// 鍦ㄩ涓満鏅姞杞藉墠鑷姩鍒涘缓 PlayerManager GameObject銆?
    /// 纭繚鍦ㄤ换浣曞満鏅姞杞芥椂 PlayerManager 閮藉凡鍦?DontDestroyOnLoad 涓氨缁€?
    /// </summary>
    [RuntimeInitializeOnLoadMethod(RuntimeInitializeLoadType.BeforeSceneLoad)]
    private static void AutoInitialize()
    {
        if (Instance != null) return;

        var go = new GameObject("[PlayerManager]");
        go.AddComponent<PlayerManager>();
    }

    private void Awake()
    {
        if (Instance != null && Instance != this)
        {
            Destroy(gameObject);
            return;
        }
        Instance = this;
        DontDestroyOnLoad(gameObject);

        // Editor: 鑷姩鏌ユ壘 Player 棰勫埗浣擄紝鍏嶅幓鎵嬪姩閰嶇疆
        // Build: 闇€灏?Player.prefab 鏀惧叆 Resources/ 鐩綍
        if (_playerPrefab == null)
        {
            _playerPrefab = ResolvePlayerPrefab();
        }
    }

    private void OnEnable()
    {
        SceneManager.sceneLoaded += OnSceneLoaded;
    }

    private void OnDisable()
    {
        SceneManager.sceneLoaded -= OnSceneLoaded;
    }

    // ==================== 鍦烘櫙鍔犺浇鍥炶皟 ====================

    /// <summary>姣忔鍦烘櫙鍔犺浇鍚庤Е鍙戯紝纭繚鍦烘櫙涓瓨鍦?Player</summary>
    private void OnSceneLoaded(Scene scene, LoadSceneMode mode)
    {
        // Start / Result 绛夐潪娓告垙鍦烘櫙涓嶇敓鎴愩€佷笉淇濈暀 Player
        if (IsNonGameplayScene(scene.name))
        {
            if (CurrentPlayer != null)
            {
                Destroy(CurrentPlayer);
                CurrentPlayer = null;
            }
            return;
        }

        var player = GameObject.FindGameObjectWithTag("Player");

        // 宸插瓨鍦?Player 鈥斺€?浼樺厛澶嶇敤锛堝彲鑳芥槸鍦烘櫙涓墜鍔ㄦ斁缃殑锛屾垨鏄笂涓€鍦烘櫙淇濈暀鐨勶級
        if (player != null)
        {
            // 棣栨娉ㄥ唽: 鏍囪涓?DontDestroyOnLoad 浠ヤ究璺ㄥ満鏅繚鐣?
            if (player != CurrentPlayer)
            {
